/* Frontend client for the QuanLyDuAn API gateway. */
let people = [];
/* Demo records are kept only as local placeholders until the first API response. */
let legacyPeople = [];
let projects = [];
let legacyProjects = [];
let tasks = [];
let legacyTasks = [];
let attendance = [];
let legacyAttendance = [];
let leaveRequests = [];
let legacyLeaveRequests = [];
let payroll = [];
let legacyPayroll = [];
let currentPage='dashboard', projectFilter='all', taskFilter='all', attendanceFilter='all', leaveFilter='all', globalQuery='';
const listPageSize=10;
const listPages={projects:1,tasks:1,attendance:1,leave:1,payroll:1,people:1};
const listFilters={taskProject:'all',taskPriority:'all',attendanceMonth:'all',peopleRole:'all',peopleActive:'all'};
const apiBase=window.WORKLY_CONFIG?.apiBaseUrl||'https://localhost:7199';
const state={token:localStorage.getItem('workly.accessToken')||'',refreshToken:localStorage.getItem('workly.refreshToken')||'',userId:localStorage.getItem('workly.userId')||'',username:localStorage.getItem('workly.username')||'',role:roleFromToken(localStorage.getItem('workly.accessToken')||''),projects:[],tasks:[],assignments:[],attendance:[],leave:[],payroll:[],payRuns:[],users:people.map(u=>({id:u.id,name:u.name,role:u.role,active:true})),policies:[],apiReady:false,apiError:'',loading:false};
const apiPaths={projects:'/api-user/duan',tasks:'/api-user/congviec',assignments:'/api-user/phancong',attendance:'/api-user/chamcong',leave:'/api-user/nghiphep',payroll:'/api-user/phieuluong',payRuns:'/api-admin/chaybangluong',users:'/api-admin/nguoidung',policies:'/api-admin/chinhsachluong'};
function roleFromToken(token){try{const payload=token.split('.')[1].replace(/-/g,'+').replace(/_/g,'/');const p=JSON.parse(atob(payload.padEnd(Math.ceil(payload.length/4)*4,'=')));const role=p['http://schemas.microsoft.com/ws/2008/06/identity/claims/role']||p['http://schemas.xmlsoap.org/ws/2005/05/identity/claims/role']||p.role||p.roles||p.vaitro||p.vaiTro||'';return Array.isArray(role)?role.join(','):String(role)}catch{return ''}}
async function api(path,options={}){const headers={...(options.body?{'Content-Type':'application/json'}:{}),...(options.headers||{})};if(state.token)headers.Authorization=`Bearer ${state.token}`;let response;try{response=await fetch(`${apiBase}${path}`,{...options,headers})}catch(error){throw new Error(`Không kết nối được API Gateway tại ${apiBase}. Hãy chạy gateway, tin cậy chứng chỉ HTTPS và dùng Live Server/localhost. (${error.message})`)}if(response.status===401&&path!=='/api/core/login')logout(false);if(!response.ok){let detail='';try{detail=await response.text()}catch{}if(response.status===401)throw new Error('Phiên đăng nhập hết hạn hoặc không có quyền truy cập. Vui lòng đăng nhập lại.');if(response.status===403)throw new Error('Tài khoản không có quyền thực hiện thao tác này.');throw new Error(detail||`API trả về lỗi HTTP ${response.status}`)}if(response.status===204)return null;const type=response.headers.get('content-type')||'';return type.includes('application/json')?response.json():response.text()}
async function refreshAccessToken(){return false}
function saveSession(data){const previousToken=state.token;const previousUserId=state.userId;state.token=data.token||'';state.refreshToken=data.refreshToken||'';state.userId=data.userId||data.maNguoiDung||'';state.username=data.username||data.tendangnhap||'';state.role=data.role||roleFromToken(state.token)||'';if(previousToken!==state.token||previousUserId!==state.userId){currentPage='dashboard';for(const key of ['projects','tasks','assignments','attendance','leave','payroll','payRuns','users','policies'])state[key]=[];for(const key of ['projectsLoaded','tasksLoaded','assignmentsLoaded','attendanceLoaded','leaveLoaded','payrollLoaded','payRunsLoaded','usersLoaded','policiesLoaded','weekLoaded'])state[key]=false;state.weekSummary=null;for(const key of ['projects','tasks','attendance','leave','payroll','people'])listPages[key]=1}for(const [k,v] of Object.entries({accessToken:state.token,refreshToken:state.refreshToken,userId:state.userId,username:state.username,role:state.role})){if(v)localStorage.setItem(`workly.${k}`,v);else localStorage.removeItem(`workly.${k}`)}}
function logout(show=true){state.token='';state.refreshToken='';state.userId='';state.username='';state.role='';for(const k of ['accessToken','refreshToken','userId','username','role'])localStorage.removeItem(`workly.${k}`);if(show){toast('Đã đăng xuất.');render()} }
function assignedRoles(){return String(state.role||'').split(/[,;\s]+/).map(role=>role.trim().toLowerCase()).filter(Boolean)}
function needsRole(...roles){const current=assignedRoles();return roles.some(role=>current.includes(role.toLowerCase()))}
function canAccessPage(page){if(needsRole('admin'))return ['dashboard','projects','tasks','attendance','leave','payroll','people','reports'].includes(page);if(needsRole('pm'))return ['dashboard','projects','tasks','attendance','leave','people','reports'].includes(page);if(needsRole('accountant'))return ['dashboard','attendance','payroll'].includes(page);if(needsRole('employee'))return ['dashboard','tasks','attendance','leave','payroll'].includes(page);return page==='dashboard'}
function isMyAttendance(record){return String(record?.userId||'').trim().toLowerCase()===String(state.userId||'').trim().toLowerCase()&&Boolean(state.userId)}
function normalizeArray(value){if(Array.isArray(value))return value;if(Array.isArray(value?.data))return value.data;return []}
function projectDTO(p){return{id:p.maduan||p.maDuAn||p.id,name:p.tenduan||p.tenDuAn||'',description:p.motada||p.moTaDA||'',status:p.trangthai||p.trangThai||'Planning',ownerId:p.nguoitao||p.nguoiTao||'',start:dateOnly(p.ngaybatdau||p.ngayBatDau),end:dateOnly(p.ngayketthuc||p.ngayKetThuc)}}
function taskDTO(t){return{id:t.macongviec||t.maCongViec||t.id,title:t.tieude||t.tieuDe||'',description:t.mota||t.moTa||'',projectId:t.maduan||t.maDuAn||'',status:t.trangthai||t.trangThai||'Todo',priority:t.mucdouutien||t.mucDoUuTien||'Medium',start:dateOnly(t.ngaybatdau||t.ngayBatDau),due:dateOnly(t.dateline||t.deadline),creator:t.nguoitao||t.nguoiTao||''}}
function attendanceDTO(a){return{id:a.mabangchamcong||a.maBangChamCong||a.id,userId:a.manguoidung||a.maNguoiDung||'',taskId:a.macongviec||a.maCongViec||'',date:dateOnly(a.ngaylamviec||a.ngayLamViec),hours:Number(a.sogiolam??a.soGioLam??0),status:a.trangthai||a.trangThai||'Pending',reviewer:a.nguoiduyet||a.nguoiDuyet||'',reason:a.lydoTuChoi||a.lyDoTuChoi||''}}
function leaveDTO(a){return{id:a.manghiphep||a.maNghiPhep||a.id,userId:a.manguoidung||a.maNguoiDung||'',type:a.loainghiphep||a.loaiNghiPhep||'Leave',start:dateOnly(a.ngaybatdau||a.ngayBatDau),end:dateOnly(a.ngayketthuc||a.ngayKetThuc),hours:Number(a.sogiolam??a.soGioLam??0),status:a.trangthai||a.trangThai||'Pending',reason:a.lydo||a.lyDo||'',rejectReason:a.lydoTuChoi||a.lyDoTuChoi||''}}
function userDTO(u){return{id:u.manguoidung||u.maNguoiDung||u.id,name:u.hoten||u.hoTen||u.tendangnhap||u.tenDangNhap||'',username:u.tendangnhap||u.tenDangNhap||'',email:u.email||'',role:u.vaitro||u.vaiTro||'',active:u.trangthai??u.trangThai??true}}
function userDTO(u){return{id:u.manguoidung||u.maNguoiDung||u.id,name:u.hoten||u.hoTen||u.tendangnhap||u.tenDangNhap||'',username:u.tendangnhap||u.tenDangNhap||'',email:u.email||'',role:u.vaitro||u.vaiTro||'',active:u.trangthai??u.trangThai??true}}
function payrollDTO(p){return{id:p.maphieuluong||p.maPhieuLuong||p.id,runId:p.machayluong||p.maChayLuong||'',userId:p.manguoidung||p.maNguoiDung||'',policyId:p.machinhsach||p.maChinhSach||'',hours:Number(p.tonggiolam??p.tongGioLam??0),ot:Number(p.tonggiolamthem??p.tongGioLamThem??0),gross:Number(p.tongluong??p.tongLuong??0),deduction:Number(p.khoantru??p.khoanTru??0),net:Number(p.luongnhanduoc??p.luongNhanDuoc??0)}}
function payRunDTO(p){return{id:p.machayluong||p.maChayLuong||p.id,start:dateOnly(p.ngaybatdaukyluong||p.ngayBatDauKyLuong),end:dateOnly(p.ngayketthuckyluong||p.ngayKetThucKyLuong),status:p.trangthai||p.trangThai||'Draft'}}
function leavePage(){let rows=leaveRequests.filter(a=>(leaveFilter==='all'||a.status===leaveFilter)&&`${a.name} ${a.type} ${a.id}`.toLowerCase().includes(globalQuery));return `${heading('Nghỉ phép & OT','Dữ liệu yêu cầu được tải từ CSDL.',needsRole('employee')?`<button class="btn btn-primary" data-action="new-leave">＋ Tạo yêu cầu</button>`:`<button class="btn btn-quiet" data-action="export">⇩ Xuất CSV</button>`)}${pageTabs([['all','Tất cả yêu cầu'],['Pending','Chờ duyệt'],['Leave','Nghỉ phép'],['OT','Làm thêm giờ']],leaveFilter)}<div class="toolbar"><input id="pageSearch" placeholder="⌕  Tìm nhân viên..." value="${globalQuery}"></div><article class="panel"><div class="table-overflow"><table class="data-table"><thead><tr><th>MÃ ĐƠN</th><th>NHÂN VIÊN</th><th>LOẠI</th><th>THỜI GIAN</th><th>SỐ GIỜ OT</th><th>LÝ DO</th><th>TRẠNG THÁI</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td><b class="table-main">${escapeHTML(r.id)}</b></td><td>${escapeHTML(r.name)}</td><td>${r.type==='OT'?'Làm thêm':'Nghỉ phép'}</td><td>${dateVN(r.start)}${r.start!==r.end?' – '+dateVN(r.end):''}</td><td>${r.type==='OT'?r.hours+' giờ':'—'}</td><td>${escapeHTML(r.reason||'—')}</td><td>${badge(r.status)}</td><td>${r.status==='Pending'&&needsRole('admin','pm')?`<button class="text-link" data-action="review-leave" data-id="${r.id}">Duyệt</button>`:'—'}</td></tr>`).join('')||'<tr><td colspan="8" class="empty-state">Không có yêu cầu trong CSDL.</td></tr>'}</tbody></table></div><div class="table-footer"><span>${rows.length} yêu cầu từ API</span></div></article>`}
function dateOnly(v){if(!v)return'';return String(v).slice(0,10)}
function joinName(id){return state.users.find(u=>u.id===id)?.name||people.find(u=>u.id===id)?.name||id||'—'}
function joinTask(id){return state.tasks.find(t=>t.id===id)?.title||id||'—'}
function joinProject(id){return state.projects.find(p=>p.id===id)?.name||id||'—'}
function hydrateSampleLists(){projects=state.projects.map(p=>({id:p.id,name:p.name,status:p.status,owner:joinName(p.ownerId),start:p.start,end:p.end,progress:state.tasks.filter(t=>t.projectId===p.id&&t.status==='Done').length?Math.round(state.tasks.filter(t=>t.projectId===p.id&&t.status==='Done').length/Math.max(1,state.tasks.filter(t=>t.projectId===p.id).length)*100):0,tasks:state.tasks.filter(t=>t.projectId===p.id).length,icon:'▦',tone:'purple',description:p.description}));tasks=state.tasks.map(t=>({id:t.id,title:t.title,project:joinProject(t.projectId),status:t.status,priority:t.priority,assignee:joinName(state.assignments.find(a=>(a.Macongviec||a.macongviec)===t.id)?.Manguoidung||t.creator),initials:initials(joinName(t.creator)||'NV'),due:t.due||'',projectId:t.projectId,description:t.description,start:t.start}));attendance=state.attendance.map(a=>({id:a.id,userId:a.userId,name:joinName(a.userId),initials:initials(joinName(a.userId)||'NV'),task:joinTask(a.taskId),taskId:a.taskId,project:state.tasks.find(t=>t.id===a.taskId)?.projectId||'',date:a.date,hours:a.hours,status:a.status,reason:a.reason}));leaveRequests=state.leave.map(a=>({id:a.id,name:joinName(a.userId),initials:initials(joinName(a.userId)||'NV'),type:a.type==='OT'?'OT':'Leave',start:a.start,end:a.end,hours:a.hours,status:a.status,reason:a.reason,rejectReason:a.rejectReason}));payroll=state.payroll.map(p=>({id:p.id,userId:p.userId,name:joinName(p.userId),period:(state.payRuns.find(r=>r.id===p.runId)?.start||'').slice(0,7),hours:p.hours,ot:p.ot,gross:p.gross,deduction:p.deduction,net:p.net,runId:p.runId,policyId:p.policyId}));people=state.users.map(u=>({id:u.id,name:u.name,role:u.role,initials:initials(u.name||u.username||'NV'),color:'purple',email:u.email,active:u.active}))}
async function loadDataFor(page=currentPage){if(!state.token||!canAccessPage(page))return;if(state.loading)return;state.loading=true;state.apiError='';try{const jobs=[];if(needsRole('admin','pm')&&['dashboard','projects','tasks','reports'].includes(page)){if(!state.projectsLoaded)jobs.push(api(apiPaths.projects).then(x=>{state.projects=normalizeArray(x).map(projectDTO);state.projectsLoaded=true}));if(!state.tasksLoaded)jobs.push(api(`${apiPaths.tasks}/all`).then(x=>{state.tasks=normalizeArray(x).map(taskDTO);state.tasksLoaded=true}));if(!state.assignmentsLoaded)jobs.push(api(`${apiPaths.assignments}/all`).then(x=>{state.assignments=normalizeArray(x);state.assignmentsLoaded=true}))}if(needsRole('admin','pm','accountant','employee')&&['dashboard','attendance','reports'].includes(page)&&!state.attendanceLoaded){const endpoint=needsRole('employee')&&!needsRole('admin','pm','accountant')?`${apiPaths.attendance}/me`:page==='reports'||(page==='attendance'&&needsRole('admin','pm'))?`${apiPaths.attendance}/all`:needsRole('admin','pm')?`${apiPaths.attendance}/pending`:apiPaths.attendance;jobs.push(api(endpoint).then(x=>{state.attendance=normalizeArray(x).map(attendanceDTO);if(needsRole('employee')&&!needsRole('admin','pm','accountant'))state.attendance=state.attendance.filter(isMyAttendance);state.attendanceLoaded=true}))}if(needsRole('admin','pm','employee')&&['dashboard','leave'].includes(page)&&!state.leaveLoaded)jobs.push(api(needsRole('admin','pm')?(page==='leave'?`${apiPaths.leave}/all`:`${apiPaths.leave}/pending`):`${apiPaths.leave}/me`).then(x=>{state.leave=normalizeArray(x).map(leaveDTO);state.leaveLoaded=true}));if(needsRole('admin','accountant')&&['payroll','dashboard'].includes(page)){if(!state.payrollLoaded)jobs.push(api(apiPaths.payroll).then(x=>{state.payroll=normalizeArray(x).map(payrollDTO);state.payrollLoaded=true}));if(!state.payRunsLoaded)jobs.push(api(apiPaths.payRuns).then(x=>{state.payRuns=normalizeArray(x).map(payRunDTO);state.payRunsLoaded=true}));if(!state.policiesLoaded)jobs.push(api(apiPaths.policies).then(x=>{state.policies=normalizeArray(x);state.policiesLoaded=true}))}if(needsRole('admin')&&['dashboard','people','reports'].includes(page)&&!state.usersLoaded)jobs.push(api(apiPaths.users).then(x=>{state.users=normalizeArray(x).map(userDTO);state.usersLoaded=true}));await Promise.all(jobs);hydrateSampleLists()}catch(error){state.apiError=error.message;if(!state.projectsLoaded)state.projects=[];if(!state.tasksLoaded)state.tasks=[];if(!state.attendanceLoaded)state.attendance=[];if(!state.leaveLoaded)state.leave=[];if(!state.payrollLoaded)state.payroll=[];if(!state.usersLoaded)state.users=[];hydrateSampleLists()}finally{state.loading=false;render()}}
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const money=n=>new Intl.NumberFormat('vi-VN').format(n)+' ₫';
const dateVN=s=>new Date(s+'T00:00:00').toLocaleDateString('vi-VN',{day:'2-digit',month:'2-digit',year:'numeric'});
const shortDate=s=>new Date(s+'T00:00:00').toLocaleDateString('vi-VN',{day:'2-digit',month:'short'});
const statusText=s=>({Planning:'Lên kế hoạch',InProgress:'Đang thực hiện',Completed:'Hoàn thành',OnHold:'Tạm dừng',Todo:'Cần làm',Done:'Hoàn thành',Pending:'Chờ duyệt',Approved:'Đã duyệt',Rejected:'Từ chối',Draft:'Bản nháp'}[s]||s);
const badge=s=>`<span class="status-pill ${s==='InProgress'?'status-progress':s==='Todo'||s==='Pending'||s==='Draft'?'status-pending':''}">${statusText(s)}</span>`;
const avatar=(initials,tone='purple')=>`<span class="avatar avatar-${tone}">${initials}</span>`;
const initials=name=>name.split(' ').slice(-2).map(x=>x[0]).join('').toUpperCase();
function metric(icon,tone,label,value,foot){return `<article class="metric-card"><div class="metric-top"><span>${label}</span><span class="metric-icon mi-${tone}">${icon}</span></div><div class="metric-value">${value}</div><div class="metric-foot">${foot}</div></article>`}
function heading(title,sub,actions=''){return `<div class="page-heading"><div><div class="eyebrow">QUẢN LÝ DỰ ÁN & CHẤM CÔNG / ${currentPage==='dashboard'?'DASHBOARD':title.toUpperCase()}</div><h1>${title}</h1><p>${sub}</p></div><div class="heading-actions">${actions}</div></div>`}
function pageTabs(items,active){return `<div class="page-tabs">${items.map(([id,label])=>`<button class="page-tab ${id===active?'active':''}" data-tab="${id}">${label}</button>`).join('')}</div>`}
function pageSlice(rows,key){const pages=Math.max(1,Math.ceil(rows.length/listPageSize));listPages[key]=Math.min(Math.max(1,listPages[key]||1),pages);const page=listPages[key],start=(page-1)*listPageSize;return{rows:rows.slice(start,start+listPageSize),total:rows.length,page,pages,start,end:Math.min(start+listPageSize,rows.length)}}
function listFooter(info,key,label){const buttons=[];if(info.pages>1){buttons.push(`<button data-list-page="${key}" data-target-page="${info.page-1}" ${info.page===1?'disabled':''} aria-label="Trang trước">‹</button>`);for(let p=1;p<=info.pages;p++)buttons.push(`<button data-list-page="${key}" data-target-page="${p}" class="${p===info.page?'active':''}" aria-current="${p===info.page?'page':'false'}">${p}</button>`);buttons.push(`<button data-list-page="${key}" data-target-page="${info.page+1}" ${info.page===info.pages?'disabled':''} aria-label="Trang sau">›</button>`)}const range=info.total?`Hiển thị ${info.start+1}–${info.end} trong ${info.total} ${label}`:`0 ${label}`;return `<div class="table-footer"><span>${range}</span>${info.pages>1?`<nav class="pager" aria-label="Phân trang">${buttons.join('')}</nav>`:''}</div>`}
function taskRow(t){return `<tr><td class="task-name">${t.title}</td><td class="task-project">${t.project}</td><td><span class="person-cell"><span class="mini-avatar">${t.initials}</span>${t.assignee}</span></td><td>${badge(t.status)}</td><td class="priority priority-${t.priority.toLowerCase()}">◆ ${t.priority==='High'?'Cao':t.priority==='Medium'?'Trung bình':'Thấp'}</td><td>${shortDate(t.due)}</td></tr>`}
function taskTable(rows,compact=false){return `<div class="table-overflow"><table class="task-table"><thead><tr><th>CÔNG VIỆC</th><th>DỰ ÁN</th><th>NGƯỜI PHỤ TRÁCH</th><th>TRẠNG THÁI</th><th>ƯU TIÊN</th><th>HẠN CHÓT</th></tr></thead><tbody>${rows.length?rows.map(taskRow).join(''):`<tr><td colspan="6" class="empty-state">Không có công việc phù hợp.</td></tr>`}</tbody></table></div>`}
function projectRows(){return projects.slice(0,5).map(p=>`<div class="project-row"><span class="project-logo ${p.tone}">${p.icon}</span><div class="project-info"><b>${p.name}</b><small>${p.tasks} công việc · ${statusText(p.status)}</small><div class="progress-track"><div class="progress-bar" style="width:${p.progress}%"></div></div></div><span class="progress-label">${p.progress}%</span></div>`).join('')}
function activity(){return `<div class="activity-list"><div class="activity-item"><span class="activity-avatar">TB</span><div class="activity-copy"><b>Trần Văn Bình</b> đã tạo dự án <b>Quản lý dự án</b><small>Hôm nay, 09:42 · DA030</small></div></div><div class="activity-item"><span class="activity-avatar" style="background:#e8f7f1;color:#25a780">NH</span><div class="activity-copy"><b>Nguyễn Thị Hà</b> đã hoàn thành <b>Đặt món trực tuyến</b><small>Hôm nay, 09:18 · CV018</small></div></div><div class="activity-item"><span class="activity-avatar" style="background:#fff3e5;color:#ca8b35">BM</span><div class="activity-copy"><b>Bùi Văn Minh</b> gửi bảng chấm công <b>8 giờ</b><small>Hôm qua, 17:30 · CC030</small></div></div><div class="activity-item"><span class="activity-avatar" style="background:#fceced;color:#d36570">VL</span><div class="activity-copy"><b>Vũ Thị Lan</b> gửi yêu cầu <b>làm thêm giờ</b><small>Hôm qua, 16:05 · NP029</small></div></div></div>`}
function dashboard(){return `${heading('Chào buổi sáng, An 👋','Đây là những gì đang diễn ra trong workspace của bạn.',`<select class="date-select" id="dashboardRange"><option>Tháng 10, 2026</option><option>Tháng 9, 2026</option></select><button class="btn btn-primary" data-action="new-task">＋ Tạo công việc</button>`)}<div class="metrics">${metric('▦','purple','Tổng dự án','24','<span class="trend">↑ 12%</span> so với tháng trước')}${metric('☷','green','Công việc đang chạy','36','<span class="trend">↑ 8%</span> so với tháng trước')}${metric('◷','orange','Chờ duyệt chấm công','8','Cần xử lý trong hôm nay')}${metric('＄','blue','Quỹ lương tháng này','128,5tr','6 nhân viên · kỳ tháng 9')}</div><div class="dashboard-grid"><article class="panel"><div class="panel-header"><div><h2 class="panel-title">Tổng quan hoạt động</h2><div class="panel-subtitle">Tiến độ công việc trong 6 tháng gần đây</div></div><div class="chart-legend"><span><i class="legend-dot" style="background:#695be5"></i>Công việc</span><span><i class="legend-dot" style="background:#52c5a1"></i>Hoàn thành</span></div></div><div class="chart-wrap"><svg viewBox="0 0 600 205" preserveAspectRatio="none" role="img" aria-label="Biểu đồ công việc 6 tháng"><defs><linearGradient id="areaFill" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#695be5" stop-opacity=".15"/><stop offset="1" stop-color="#695be5" stop-opacity="0"/></linearGradient></defs><g class="chart-grid"><line x1="38" y1="25" x2="590" y2="25"/><line x1="38" y1="65" x2="590" y2="65"/><line x1="38" y1="105" x2="590" y2="105"/><line x1="38" y1="145" x2="590" y2="145"/><line x1="38" y1="185" x2="590" y2="185"/><text x="3" y="28">40</text><text x="3" y="68">30</text><text x="3" y="108">20</text><text x="3" y="148">10</text><text x="10" y="188">0</text></g><path class="chart-area" d="M45 130 C90 120 105 105 145 110 S205 82 245 90 S305 53 345 71 S405 42 445 52 S510 28 575 38 L575 185 L45 185Z"/><path class="chart-line-a" d="M45 130 C90 120 105 105 145 110 S205 82 245 90 S305 53 345 71 S405 42 445 52 S510 28 575 38"/><path class="chart-line-b" d="M45 153 C90 149 112 139 145 145 S210 119 245 132 S310 105 345 117 S410 86 445 101 S510 73 575 79"/><circle class="chart-point" cx="445" cy="52" r="4"/><g class="chart-x"><text x="40" y="201">T5</text><text x="143" y="201">T6</text><text x="243" y="201">T7</text><text x="343" y="201">T8</text><text x="443" y="201">T9</text><text x="568" y="201">T10</text></g></svg></div></article><article class="panel"><div class="panel-header"><div><h2 class="panel-title">Dự án theo trạng thái</h2><div class="panel-subtitle">Phân bổ 24 dự án hiện tại</div></div><button class="text-link" data-page="projects">Chi tiết →</button></div><div class="project-summary"><div class="donut"><svg viewBox="0 0 100 100"><circle class="track" cx="50" cy="50" r="40"/><circle class="seg1" cx="50" cy="50" r="40"/><circle class="seg2" cx="50" cy="50" r="40"/><circle class="seg3" cx="50" cy="50" r="40"/></svg><div class="donut-center"><b>24</b><span>tổng dự án</span></div></div><div class="legend-list"><div class="legend-row"><span><i class="legend-dot" style="background:#6757e8"></i>Đang thực hiện</span><b>10</b></div><div class="legend-row"><span><i class="legend-dot" style="background:#4fc39b"></i>Hoàn thành</span><b>7</b></div><div class="legend-row"><span><i class="legend-dot" style="background:#f0ae55"></i>Lên kế hoạch</span><b>5</b></div><div class="legend-row"><span><i class="legend-dot" style="background:#dfe1e9"></i>Tạm dừng</span><b>2</b></div></div></div><div class="project-list">${projectRows()}</div></article></div><div class="lower-grid"><article class="panel table-panel"><div class="panel-header"><div><h2 class="panel-title">Công việc gần đây</h2><div class="panel-subtitle">Theo dõi các đầu việc mới nhất trong dự án</div></div><button class="text-link" data-page="tasks">Xem tất cả →</button></div>${taskTable(tasks.slice(0,4),true)}</article><article class="panel"><div class="panel-header"><div><h2 class="panel-title">Hoạt động gần đây</h2><div class="panel-subtitle">Cập nhật mới nhất từ nhóm của bạn</div></div><button class="text-link">···</button></div>${activity()}</article></div>`}
function dashboardLive(){const payrollTotal=payroll.reduce((sum,p)=>sum+p.net,0);const pendingAttendance=attendance.filter(a=>a.status==='Pending').length;const pendingLeave=leaveRequests.filter(a=>a.status==='Pending').length;return `${heading(`Xin chào, ${escapeHTML(state.username||'bạn')} 👋`,'Số liệu dưới đây được tải từ API của hệ thống.',needsRole('admin','pm')?`<button class="btn btn-primary" data-action="new-task">＋ Tạo công việc</button>`:'')}<div class="metrics">${metric('▦','purple','Dự án',state.projectsLoaded?state.projects.length:'—',state.projectsLoaded?'Dữ liệu API':'Không có quyền truy cập')}${metric('☷','green','Công việc chưa hoàn tất',state.tasksLoaded?state.tasks.filter(t=>t.status!=='Done').length:'—',state.tasksLoaded?`${state.tasks.length} công việc tải từ API`:'Không có quyền truy cập')}${metric('◷','orange','Chấm công chờ duyệt',state.attendanceLoaded?pendingAttendance:'—',state.attendanceLoaded?`${attendance.length} bản ghi tải từ API`:'Không có quyền truy cập')}${metric('＄','blue','Lương thực nhận',state.payrollLoaded?money(payrollTotal):'—',state.payrollLoaded?`${payroll.length} phiếu lương từ API`:'Chỉ Admin / Kế toán')}</div><div class="dashboard-grid"><article class="panel"><div class="panel-header"><div><h2 class="panel-title">Dự án</h2><div class="panel-subtitle">Dữ liệu trực tiếp từ endpoint DuAn</div></div><button class="text-link" data-page="projects">Xem tất cả →</button></div>${projects.length?`<div class="project-list">${projectRows()}</div>`:'<div class="empty-state">Không có dữ liệu dự án hoặc tài khoản không có quyền xem.</div>'}</article><article class="panel"><div class="panel-header"><div><h2 class="panel-title">Yêu cầu cần xử lý</h2><div class="panel-subtitle">Chấm công và nghỉ phép đang chờ</div></div><button class="text-link" data-page="attendance">Mở chấm công →</button></div><div class="legend-list"><div class="legend-row"><span>Chấm công chờ duyệt</span><b>${state.attendanceLoaded?pendingAttendance:'—'}</b></div><div class="legend-row"><span>Đơn nghỉ / OT chờ duyệt</span><b>${state.leaveLoaded?pendingLeave:'—'}</b></div></div>${state.leaveLoaded?`<p class="panel-subtitle" style="margin-top:16px">${leaveRequests.slice(0,3).map(x=>`${escapeHTML(x.name)} · ${x.type==='OT'?'Làm thêm giờ':'Nghỉ phép'} · ${escapeHTML(x.id)}`).join('<br>')||'Không có yêu cầu chờ duyệt.'}</p>`:''}</article></div><div class="lower-grid"><article class="panel table-panel"><div class="panel-header"><div><h2 class="panel-title">Công việc</h2><div class="panel-subtitle">Các đầu việc lấy từ API CongViec</div></div><button class="text-link" data-page="tasks">Xem tất cả →</button></div>${taskTable(tasks.slice(0,5))}</article><article class="panel"><div class="panel-header"><div><h2 class="panel-title">Phiếu lương gần đây</h2><div class="panel-subtitle">Thông tin do API trả về</div></div><button class="text-link" data-page="payroll">Bảng lương →</button></div>${payroll.slice(0,4).map(p=>`<div class="approval-card"><span class="approval-initial">＄</span><div class="approval-details"><b>${escapeHTML(joinName(p.userId))}</b><small>${escapeHTML(p.id)} · ${money(p.net)}</small></div></div>`).join('')||'<div class="empty-state">Không có phiếu lương hoặc tài khoản không có quyền xem.</div>'}</article></div>`}
function projectsPage(){let filtered=projects.filter(p=>(projectFilter==='all'||p.status===projectFilter)&&`${p.name} ${p.id} ${p.owner}`.toLowerCase().includes(globalQuery));const page=pageSlice(filtered,'projects');return `${heading('Dự án','Dự án lấy từ CSDL qua API.',`<button class="btn btn-primary" data-action="new-project">＋ Tạo dự án</button>`)}${pageTabs([['all','Tất cả dự án'],['InProgress','Đang thực hiện'],['Planning','Lên kế hoạch'],['Completed','Hoàn thành']],projectFilter)}<div class="toolbar"><input id="pageSearch" placeholder="⌕  Tìm dự án..." value="${escapeHTML(globalQuery)}"><select id="projectStatus"><option value="all">Tất cả trạng thái</option><option value="InProgress">Đang thực hiện</option><option value="Planning">Lên kế hoạch</option><option value="Completed">Hoàn thành</option></select></div><article class="panel"><div class="table-overflow"><table class="data-table"><thead><tr><th>DỰ ÁN</th><th>QUẢN LÝ</th><th>NGÀY BẮT ĐẦU</th><th>HẠN DỰ KIẾN</th><th>TIẾN ĐỘ</th><th>TRẠNG THÁI</th></tr></thead><tbody>${page.rows.map(p=>`<tr><td><span class="person-cell"><span class="project-logo ${p.tone}">${p.icon}</span><span><b class="table-main">${escapeHTML(p.name)}</b><small class="table-sub">${escapeHTML(p.id)} · ${p.tasks} công việc</small></span></span></td><td>${escapeHTML(p.owner)}</td><td>${p.start?dateVN(p.start):'—'}</td><td>${p.end?dateVN(p.end):'—'}</td><td><span class="progress-label">${p.progress}%</span><div class="progress-track" style="width:88px"><div class="progress-bar" style="width:${p.progress}%"></div></div></td><td>${badge(p.status)}</td></tr>`).join('')||'<tr><td colspan="6" class="empty-state">Không có dự án phù hợp.</td></tr>'}</tbody></table></div>${listFooter(page,'projects','dự án')}</article>`}
function tasksPage(){let filtered=tasks.filter(t=>(taskFilter==='all'||t.status===taskFilter)&&(listFilters.taskProject==='all'||t.projectId===listFilters.taskProject)&&(listFilters.taskPriority==='all'||t.priority===listFilters.taskPriority)&&`${t.title} ${t.project} ${t.assignee}`.toLowerCase().includes(globalQuery));const page=pageSlice(filtered,'tasks');return `${heading('Công việc','Công việc lấy từ CSDL qua API.',`<button class="btn btn-primary" data-action="new-task">＋ Tạo công việc</button>`)}${pageTabs([['all','Tất cả'],['InProgress','Đang thực hiện'],['Todo','Cần làm'],['Done','Hoàn thành']],taskFilter)}<div class="toolbar"><input id="pageSearch" placeholder="⌕  Tìm công việc..." value="${escapeHTML(globalQuery)}"><select id="taskProject"><option value="all">Tất cả dự án</option>${projects.map(p=>`<option value="${escapeHTML(p.id)}">${escapeHTML(p.name)}</option>`).join('')}</select><select id="taskPriority"><option value="all">Mọi mức ưu tiên</option><option value="High">Cao</option><option value="Medium">Trung bình</option><option value="Low">Thấp</option></select></div><article class="panel">${taskTable(page.rows)}${listFooter(page,'tasks','công việc')}</article>`}
function attendanceTable(rows){return `<div class="table-overflow"><table class="data-table"><thead><tr><th>MÃ CHẤM CÔNG</th><th>NHÂN VIÊN</th><th>CÔNG VIỆC</th><th>NGÀY LÀM</th><th>SỐ GIỜ</th><th>TRẠNG THÁI</th><th>THAO TÁC</th></tr></thead><tbody>${rows.map(a=>`<tr><td><b class="table-main">${escapeHTML(a.id)}</b></td><td><span class="person-cell"><span class="mini-avatar">${a.initials}</span>${escapeHTML(a.name)}</span></td><td><span class="table-main">${escapeHTML(a.task)}</span><small class="table-sub">${escapeHTML(a.project)}</small></td><td>${a.date?dateVN(a.date):'—'}</td><td>${a.hours} giờ</td><td>${badge(a.status)}</td><td>${a.status==='Pending'&&needsRole('admin','pm')?`<button class="text-link" data-action="review-attendance" data-id="${a.id}">Duyệt</button>`:'—'}</td></tr>`).join('')||'<tr><td colspan="7" class="empty-state">Không có bản ghi chấm công trong CSDL.</td></tr>'}</tbody></table></div>`}
function attendancePage(){let filtered=attendance.filter(a=>(attendanceFilter==='all'||a.status===attendanceFilter)&&(listFilters.attendanceMonth==='all'||a.date?.slice(0,7)===listFilters.attendanceMonth)&&`${a.name} ${a.task} ${a.id}`.toLowerCase().includes(globalQuery));const page=pageSlice(filtered,'attendance');const months=[...new Set(attendance.map(a=>a.date?.slice(0,7)).filter(Boolean))].sort().reverse();return `${heading('Chấm công','Dữ liệu bản ghi được tải từ CSDL qua API.',needsRole('employee')?`<button class="btn btn-primary" data-action="new-attendance">＋ Ghi nhận giờ</button>`:'')}${pageTabs([['all','Tất cả bản ghi'],['Pending','Chờ duyệt'],['Approved','Đã duyệt'],['Rejected','Từ chối']],attendanceFilter)}<div class="toolbar"><input id="pageSearch" placeholder="⌕  Tìm nhân viên hoặc công việc..." value="${escapeHTML(globalQuery)}"><select id="attendanceMonth"><option value="all">Tất cả tháng</option>${months.map(m=>`<option value="${m}">${new Date(m+'-01T00:00:00').toLocaleDateString('vi-VN',{month:'long',year:'numeric'})}</option>`).join('')}</select></div><article class="panel">${attendanceTable(page.rows)}${listFooter(page,'attendance','bản ghi')}</article>`}
function leavePage(){let rows=leaveRequests.filter(a=>(leaveFilter==='all'||(leaveFilter==='Pending'?a.status==='Pending':leaveFilter==='Leave'?a.type==='Leave':a.type==='OT'))&&`${a.name} ${a.type} ${a.id}`.toLowerCase().includes(globalQuery));const page=pageSlice(rows,'leave');return `${heading('Nghỉ phép & OT','Yêu cầu được tải từ CSDL qua API.',needsRole('employee')?`<button class="btn btn-primary" data-action="new-leave">＋ Tạo yêu cầu</button>`:`<button class="btn btn-quiet" data-action="export">⇩ Xuất CSV</button>`)}${pageTabs([['all','Tất cả yêu cầu'],['Pending','Chờ duyệt'],['Leave','Nghỉ phép'],['OT','Làm thêm giờ']],leaveFilter)}<div class="toolbar"><input id="pageSearch" placeholder="⌕  Tìm nhân viên..." value="${escapeHTML(globalQuery)}"></div><article class="panel"><div class="table-overflow"><table class="data-table"><thead><tr><th>MÃ ĐƠN</th><th>NHÂN VIÊN</th><th>LOẠI</th><th>THỜI GIAN</th><th>SỐ GIỜ OT</th><th>LÝ DO</th><th>TRẠNG THÁI</th><th></th></tr></thead><tbody>${page.rows.map(r=>`<tr><td><b class="table-main">${escapeHTML(r.id)}</b></td><td><span class="person-cell"><span class="mini-avatar">${escapeHTML(r.initials)}</span>${escapeHTML(r.name)}</span></td><td>${r.type==='OT'?'Làm thêm':'Nghỉ phép'}</td><td>${dateVN(r.start)}${r.start!==r.end?' – '+dateVN(r.end):''}</td><td>${r.type==='OT'?r.hours+' giờ':'—'}</td><td>${escapeHTML(r.reason||'—')}</td><td>${badge(r.status)}</td><td>${r.status==='Pending'&&needsRole('admin','pm')?`<button class="text-link" data-action="review-leave" data-id="${escapeHTML(r.id)}">Duyệt</button>`:'—'}</td></tr>`).join('')||'<tr><td colspan="8" class="empty-state">Không có yêu cầu phù hợp.</td></tr>'}</tbody></table></div>${listFooter(page,'leave','yêu cầu')}</article>`}
function payrollPage(){const tab=window.payrollTab||'all';const allRows=payroll.filter(p=>`${p.name} ${p.id}`.toLowerCase().includes(globalQuery));const list=tab==='runs'?state.payRuns:tab==='policies'?state.policies:allRows;const page=pageSlice(list,`payroll_${tab}`);const table=tab==='runs'?`<table class="data-table"><thead><tr><th>MÃ KỲ</th><th>NGÀY BẮT ĐẦU</th><th>NGÀY KẾT THÚC</th><th>TRẠNG THÁI</th></tr></thead><tbody>${page.rows.map(r=>`<tr><td>${escapeHTML(r.id)}</td><td>${r.start?dateVN(r.start):'—'}</td><td>${r.end?dateVN(r.end):'—'}</td><td>${badge(r.status)}</td></tr>`).join('')||'<tr><td colspan="4" class="empty-state">Không có kỳ lương trong CSDL.</td></tr>'}</tbody></table>`:tab==='policies'?`<table class="data-table"><thead><tr><th>MÃ CHÍNH SÁCH</th><th>THÔNG TIN</th></tr></thead><tbody>${page.rows.map(p=>`<tr><td>${escapeHTML(p.machinhsach||p.maChinhSach||'')}</td><td>${escapeHTML(JSON.stringify(p))}</td></tr>`).join('')||'<tr><td colspan="2" class="empty-state">Không có chính sách lương trong CSDL.</td></tr>'}</tbody></table>`:`<table class="data-table"><thead><tr><th>MÃ PHIẾU</th><th>NHÂN VIÊN</th><th>TỔNG GIỜ</th><th>GIỜ OT</th><th>TỔNG LƯƠNG</th><th>KHẤU TRỪ</th><th>THỰC NHẬN</th></tr></thead><tbody>${page.rows.map(p=>`<tr><td><b class="table-main">${escapeHTML(p.id)}</b></td><td>${escapeHTML(joinName(p.userId))}</td><td>${p.hours} giờ</td><td>${p.ot} giờ</td><td>${money(p.gross)}</td><td>${money(p.deduction)}</td><td><b class="table-main">${money(p.net)}</b></td></tr>`).join('')||'<tr><td colspan="7" class="empty-state">Không có phiếu lương trong CSDL.</td></tr>'}</tbody></table>`;return `${heading('Bảng lương','Dữ liệu bảng lương lấy từ CSDL qua API.')}${pageTabs([['all','Phiếu lương'],['runs','Kỳ lương'],['policies','Chính sách lương']],tab)}${tab==='all'?`<div class="metrics">${metric('＄','purple','Tổng thực nhận',money(allRows.reduce((sum,p)=>sum+p.net,0)),`${allRows.length} phiếu lương từ API`)}</div><div class="toolbar"><input id="pageSearch" placeholder="⌕  Tìm nhân viên..." value="${escapeHTML(globalQuery)}"></div>`:''}<article class="panel"><div class="table-overflow">${table}</div>${listFooter(page,`payroll_${tab}`,tab==='runs'?'kỳ lương':tab==='policies'?'chính sách':'phiếu lương')}</article>`}
function peoplePage(){const rows=people.filter(p=>(listFilters.peopleRole==='all'||p.role.toLowerCase()===listFilters.peopleRole.toLowerCase())&&(listFilters.peopleActive==='all'||String(Boolean(p.active))===listFilters.peopleActive)&&`${p.name} ${p.id} ${p.role} ${p.email}`.toLowerCase().includes(globalQuery));const page=pageSlice(rows,'people');return `${heading('Nhân sự','Danh sách tài khoản nhân sự lấy từ CSDL qua API.') }<div class="toolbar"><input id="pageSearch" placeholder="⌕  Tìm nhân viên..." value="${escapeHTML(globalQuery)}"><select id="peopleRole"><option value="all">Tất cả vai trò</option>${[...new Set(people.map(p=>p.role).filter(Boolean))].map(r=>`<option value="${escapeHTML(r)}">${escapeHTML(({PM:'Quản lý dự án',Accountant:'Kế toán',Employee:'Nhân viên'}[r]||r))}</option>`).join('')}</select><select id="peopleActive"><option value="all">Mọi trạng thái</option><option value="true">Đang hoạt động</option><option value="false">Đã khóa</option></select></div><article class="panel"><div class="table-overflow"><table class="data-table"><thead><tr><th>NHÂN VIÊN</th><th>MÃ NGƯỜI DÙNG</th><th>EMAIL</th><th>VAI TRÒ</th><th>TRẠNG THÁI</th></tr></thead><tbody>${page.rows.map(p=>`<tr><td><span class="person-line">${avatar(p.initials,p.color)}<b>${escapeHTML(p.name)}</b></span></td><td>${escapeHTML(p.id)}</td><td>${escapeHTML(p.email||'—')}</td><td>${escapeHTML(({PM:'Quản lý dự án',Accountant:'Kế toán',Employee:'Nhân viên'}[p.role]||p.role))}</td><td><span class="status-pill">${p.active?'Đang hoạt động':'Đã khóa'}</span></td></tr>`).join('')||'<tr><td colspan="5" class="empty-state">Không có dữ liệu nhân sự phù hợp.</td></tr>'}</tbody></table></div>${listFooter(page,'people','tài khoản')}</article>`}
function reportsPage(){const done=state.tasks.filter(t=>t.status==='Done').length;const total=state.tasks.length;const hours=state.attendance.filter(a=>a.status==='Approved').reduce((sum,a)=>sum+a.hours,0);const rows=projects.map(p=>`<tr><td>${escapeHTML(p.name)}</td><td>${escapeHTML(p.owner)}</td><td>${state.tasks.filter(t=>t.projectId===p.id&&t.status==='Done').length} / ${p.tasks}</td><td>${state.attendance.filter(a=>a.status==='Approved'&&state.tasks.some(t=>t.id===a.taskId&&t.projectId===p.id)).reduce((sum,a)=>sum+a.hours,0)}</td><td>${p.progress}%</td></tr>`).join('');return `${heading('Báo cáo','Tổng hợp trực tiếp từ dữ liệu đã tải qua API.')}<div class="metrics">${metric('▦','purple','Công việc hoàn thành',total?`${Math.round(done*100/total)}%`:'—',`${done} / ${total} công việc`)}${metric('◷','green','Giờ công đã duyệt',hours,`${state.attendance.filter(a=>a.status==='Approved').length} bản ghi`)}${metric('♙','orange','Nhân sự',state.users.length,'Tài khoản đã tải')}${metric('＄','blue','Tổng lương thực nhận',money(payroll.reduce((sum,p)=>sum+p.net,0)),`${payroll.length} phiếu lương`)}</div><article class="panel"><div class="panel-header"><div><h2 class="panel-title">Tóm tắt dự án</h2><div class="panel-subtitle">Tiến độ tính từ công việc và chấm công đã duyệt</div></div></div><div class="table-overflow"><table class="data-table"><thead><tr><th>DỰ ÁN</th><th>QUẢN LÝ</th><th>CÔNG VIỆC HOÀN THÀNH</th><th>GIỜ ĐÃ DUYỆT</th><th>TIẾN ĐỘ</th></tr></thead><tbody>${rows||'<tr><td colspan="5" class="empty-state">Không có dữ liệu dự án từ API.</td></tr>'}</tbody></table></div></article>`}function loginView(){return `<div class="login-wrap"><article class="panel login-card"><div class="brand login-brand"><span class="brand-mark">Q</span><span class="brand-name">Quản lý dự án &amp; chấm công</span></div><div class="eyebrow">QUẢN LÝ CÔNG VIỆC & NHÂN SỰ</div><h1>Chào mừng trở lại</h1><p>Đăng nhập bằng tài khoản Workly để tiếp tục.</p>${state.apiError?`<div class="api-error">${escapeHTML(state.apiError)}</div>`:''}<form id="loginForm"><label>Tên đăng nhập<input name="username" autocomplete="username" placeholder="Tên đăng nhập" required></label><label>Mật khẩu<input name="password" type="password" autocomplete="current-password" placeholder="Mật khẩu" required></label><button class="btn btn-primary" type="submit">Đăng nhập</button></form><small class="login-hint">API: ${escapeHTML(apiBase)} · Không lưu mật khẩu trong trình duyệt</small></article></div>`}
function escapeHTML(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function render(){if(!state.token){$('#pageContent').innerHTML=loginView();$('#breadcrumbCurrent').textContent='Đăng nhập';bindLogin();return}const views={dashboard:dashboardLive,projects:projectsPage,tasks:tasksPage,attendance:attendancePage,leave:leavePage,payroll:payrollPage,people:peoplePage,reports:reportsPage};$('#pageContent').innerHTML=`${state.apiError?`<div class="api-error"><b>Kết nối API:</b> ${escapeHTML(state.apiError)} <button class="text-link" data-action="retry">Thử lại</button></div>`:''}${state.loading?'<div class="loading-strip">Đang tải dữ liệu từ API…</div>':''}${(views[currentPage]||dashboard)()}`;$('#breadcrumbCurrent').textContent=({dashboard:'Tổng quan',projects:'Dự án',tasks:'Công việc',attendance:'Chấm công',leave:'Nghỉ phép & OT',payroll:'Bảng lương',people:'Nhân sự',reports:'Báo cáo'})[currentPage];$$('.nav-item').forEach(n=>n.classList.toggle('active',n.dataset.page===currentPage));if(currentPage==='projects')$('#projectStatus').value=projectFilter;if(currentPage==='tasks'){if($('#taskProject'))$('#taskProject').value=listFilters.taskProject;if($('#taskPriority'))$('#taskPriority').value=listFilters.taskPriority}if(currentPage==='attendance'&&$('#attendanceMonth'))$('#attendanceMonth').value=listFilters.attendanceMonth;if(currentPage==='people'){if($('#peopleRole'))$('#peopleRole').value=listFilters.peopleRole;if($('#peopleActive'))$('#peopleActive').value=listFilters.peopleActive}bindDynamic()}
function bindLogin(){const form=$('#loginForm');if(!form)return;form.onsubmit=async e=>{e.preventDefault();state.apiError='';const fd=new FormData(form);const button=form.querySelector('[type="submit"]');button.disabled=true;try{const result=await api('/api/core/login',{method:'POST',body:JSON.stringify({tendangnhap:fd.get('username'),matkhau:fd.get('password')})});if(!result.success||!result.token)throw new Error(result.message||'Đăng nhập thất bại.');saveSession({token:result.token,refreshToken:result.refreshToken,username:result.tendangnhap||fd.get('username'),userId:result.maNguoiDung||'',role:result.vaiTro||result.vaitro||''});const claims=decodeClaims(state.token);state.userId=state.userId||claims['nameid']||claims['sub']||claims['http://schemas.xmlsoap.org/ws/2005/05/identity/claims/nameidentifier']||claims['http://schemas.microsoft.com/ws/2008/06/identity/claims/nameidentifier']||'';localStorage.setItem('workly.userId',state.userId);state.apiReady=false;render();await loadDataFor(currentPage)}catch(error){state.apiError=error.message;render()}}}
function decodeClaims(token){try{return JSON.parse(atob(token.split('.')[1].replace(/-/g,'+').replace(/_/g,'/')))}catch{return {}}}
function toast(message){const t=$('#toast');t.textContent=message;t.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.classList.remove('show'),2600)}
function modal(title,fields,submitLabel='Lưu thông tin'){const form=fields.map(f=>`<div class="form-field ${f.full?'full':''}"><label>${f.label}</label>${f.options?`<select name="${f.name}" ${f.required?'required':''}>${f.options.map(o=>`<option value="${o[0]}">${o[1]}</option>`).join('')}</select>`:f.area?`<textarea name="${f.name}" placeholder="${f.placeholder||''}" ${f.required?'required':''}></textarea>`:`<input name="${f.name}" type="${f.type||'text'}" placeholder="${f.placeholder||''}" ${f.required?'required':''} ${f.value?`value="${f.value}"`:''}>`}</div>`).join('');$('#modal').innerHTML=`<div class="modal-header"><h2>${title}</h2><button class="modal-close" data-action="close-modal">×</button></div><form id="modalForm"><div class="form-grid">${form}</div><div id="modalError" class="api-error" style="display:none"></div><div class="modal-footer"><button type="button" class="btn btn-quiet" data-action="close-modal">Hủy</button><button class="btn btn-primary" type="submit">${submitLabel}</button></div></form>`;$('#modalBackdrop').classList.add('open');$('#modalForm').onsubmit=async e=>{e.preventDefault();const button=e.currentTarget.querySelector('[type=submit]');button.disabled=true;try{await submitModal(new FormData(e.currentTarget));$('#modalBackdrop').classList.remove('open');await loadDataFor(currentPage);toast('Đã lưu vào hệ thống.')}catch(error){const box=$('#modalError');box.textContent=error.message;box.style.display='block'}finally{button.disabled=false}}}
async function submitModal(fd){const v=k=>String(fd.get(k)||'').trim();let path='',body={};if(currentModalAction==='new-project'){path=apiPaths.projects;body={Maduan:v('id'),Tenduan:v('name'),Motada:v('description'),Ngaybatdau:v('start'),Ngayketthuc:v('end')||null,Trangthai:v('status'),Nguoitao:state.userId||claimUserId()}}else if(currentModalAction==='new-task'){path=apiPaths.tasks;body={Macongviec:v('id'),Maduan:v('project'),Tieude:v('title'),Mota:v('description'),Trangthai:'Todo',Mucdouutien:v('priority'),Ngaybatdau:v('start')||null,Dateline:v('due')||null,Nguoitao:state.userId||claimUserId()}}else if(currentModalAction==='new-attendance'){path=apiPaths.attendance;body={Macongviec:v('task'),Ngaylamviec:v('date'),Sogiolam:Number(v('hours'))}}else if(currentModalAction==='new-leave'){path=apiPaths.leave;body={Loainghiphep:v('type'),Ngaybatdau:v('date'),Ngayketthuc:v('end'),Sogiolam:v('type')==='OT'?Number(v('hours')):null,Lydo:v('reason')}}else if(currentModalAction==='new-payroll'){path=apiPaths.payRuns;body={Machayluong:v('id'),Ngaybatdaukyluong:v('start'),Ngayketthuckyluong:v('end'),Trangthai:'Draft'}}else if(currentModalAction==='new-person'){path=apiPaths.users;body={Manguoidung:v('id'),Tendangnhap:v('username'),matkhau:v('password'),Hoten:v('name'),Email:v('email'),Vaitro:v('role'),Trangthai:true}}else throw new Error('Không hỗ trợ thao tác này.');await api(path,{method:'POST',body:JSON.stringify(body)});for(const key of ['projectsLoaded','tasksLoaded','assignmentsLoaded','attendanceLoaded','leaveLoaded','payrollLoaded','payRunsLoaded','usersLoaded','policiesLoaded'])state[key]=false}
let currentModalAction='';function claimUserId(){const c=decodeClaims(state.token);return c['nameid']||c['sub']||c['http://schemas.xmlsoap.org/ws/2005/05/identity/claims/nameidentifier']||''}
function openCreate(kind){currentModalAction=kind;const userOptions=people.map(p=>[p.id,p.name]);if(kind==='new-project')modal('Tạo dự án',[{name:'id',label:'Mã dự án (duy nhất)',placeholder:'VD: DA031',required:true},{name:'name',label:'Tên dự án',placeholder:'VD: Cổng thông tin nội bộ',required:true},{name:'status',label:'Trạng thái',options:[['Planning','Lên kế hoạch'],['InProgress','Đang thực hiện'],['OnHold','Tạm dừng']]},{name:'start',label:'Ngày bắt đầu',type:'date',required:true},{name:'end',label:'Ngày kết thúc dự kiến',type:'date'},{name:'description',label:'Mô tả',area:true,full:true}]);if(kind==='new-task')modal('Tạo công việc',[{name:'id',label:'Mã công việc (duy nhất)',placeholder:'VD: CV031',required:true},{name:'title',label:'Tiêu đề công việc',placeholder:'Nhập tên công việc',required:true,full:true},{name:'project',label:'Dự án',options:projects.map(p=>[p.id,p.name])},{name:'priority',label:'Mức ưu tiên',options:[['High','Cao'],['Medium','Trung bình'],['Low','Thấp']]},{name:'start',label:'Ngày bắt đầu',type:'date'},{name:'due',label:'Hạn chót',type:'date'},{name:'description',label:'Mô tả',area:true,full:true}]);if(kind==='new-attendance')modal('Ghi nhận giờ làm',[{name:'task',label:'Công việc',options:tasks.map(t=>[t.id,t.title])},{name:'date',label:'Ngày làm việc',type:'date',required:true},{name:'hours',label:'Số giờ làm',type:'number',placeholder:'8',required:true},{name:'note',label:'Ghi chú',area:true,full:true}]);if(kind==='new-leave')modal('Tạo yêu cầu nghỉ phép / OT',[{name:'type',label:'Loại yêu cầu',options:[['Leave','Nghỉ phép'],['OT','Làm thêm giờ']]},{name:'date',label:'Ngày bắt đầu',type:'date',required:true},{name:'end',label:'Ngày kết thúc',type:'date',required:true},{name:'hours',label:'Số giờ OT',type:'number',placeholder:'Chỉ áp dụng cho OT'},{name:'reason',label:'Lý do',area:true,full:true,required:true}]);if(kind==='new-payroll')modal('Tạo kỳ lương',[{name:'id',label:'Mã kỳ lương (duy nhất)',placeholder:'VD: BL031',required:true},{name:'start',label:'Ngày bắt đầu kỳ',type:'date',required:true},{name:'end',label:'Ngày kết thúc kỳ',type:'date',required:true}]);if(kind==='new-person')modal('Mời nhân viên',[{name:'id',label:'Mã người dùng',required:true},{name:'name',label:'Họ và tên',required:true},{name:'email',label:'Email',type:'email',required:true},{name:'username',label:'Tên đăng nhập',required:true},{name:'password',label:'Mật khẩu tạm',type:'password',required:true},{name:'role',label:'Vai trò',options:[['Employee','Nhân viên'],['PM','Quản lý dự án'],['Accountant','Kế toán'],['Admin','Quản trị viên']]}])}
function bindDynamic(){$$('.nav-item').forEach(el=>el.onclick=()=>navigate(el.dataset.page));$$('[data-page]').filter(e=>!e.classList.contains('nav-item')).forEach(el=>el.onclick=()=>navigate(el.dataset.page));$$('[data-tab]').forEach(el=>el.onclick=()=>{const v=el.dataset.tab;if(currentPage==='projects')projectFilter=v;if(currentPage==='tasks')taskFilter=v;if(currentPage==='attendance')attendanceFilter=v;if(currentPage==='leave')leaveFilter=v;if(currentPage==='payroll')window.payrollTab=v;listPages[currentPage]=1;if(currentPage==='payroll')listPages[`payroll_${v}`]=1;render()});$('#pageSearch')?.addEventListener('input',e=>{globalQuery=e.target.value;listPages[currentPage]=1;listPages[`payroll_${window.payrollTab||'all'}`]=1;const pos=e.target.selectionStart;render();const next=$('#pageSearch');next?.focus();next?.setSelectionRange(pos,pos)});$('#globalSearch').value=globalQuery;$('#globalSearch').oninput=e=>{globalQuery=e.target.value;listPages[currentPage]=1;listPages[`payroll_${window.payrollTab||'all'}`]=1;if(currentPage==='dashboard')navigate('tasks');else render()};$('#projectStatus')?.addEventListener('change',e=>{projectFilter=e.target.value;listPages.projects=1;render()});const bindSelect=(id,key)=>$(`#${id}`)?.addEventListener('change',e=>{listFilters[key]=e.target.value;listPages[currentPage]=1;render()});bindSelect('taskProject','taskProject');bindSelect('taskPriority','taskPriority');bindSelect('attendanceMonth','attendanceMonth');bindSelect('peopleRole','peopleRole');bindSelect('peopleActive','peopleActive');$$('[data-list-page]').forEach(el=>el.onclick=()=>{const key=el.dataset.listPage;listPages[key]=Number(el.dataset.targetPage);render()});$$('[data-action]').forEach(el=>el.onclick=()=>{const {action,id}=el.dataset;if(action.startsWith('new-'))openCreate(action);if(action==='retry')loadDataFor(currentPage);if(action==='close-modal')$('#modalBackdrop').classList.remove('open');if(action==='export')exportCurrentPage();if(action==='complete-payroll')completePayroll();if(action==='details'){const p=projects.find(x=>x.id===id);toast(`${p.name} · ${statusText(p.status)} · Tiến độ ${p.progress}%`)}if(action==='payslip'){const p=payroll.find(x=>x.id===id);toast(`${p.id} · Thực nhận ${money(p.net)}`)}if(action==='review-attendance'){const a=attendance.find(x=>x.id===id);reviewModal(a,'attendance')}if(action==='review-leave'){const a=leaveRequests.find(x=>x.id===id);reviewModal(a,'leave')}})}
function reviewModal(item,type){const title=type==='attendance'?'Duyệt bảng chấm công':'Duyệt yêu cầu nghỉ phép / OT';$('#modal').innerHTML=`<div class="modal-header"><h2>${title}</h2><button class="modal-close" data-action="close-modal">×</button></div><div class="notice-banner" style="margin:0"><span>${type==='attendance'?'◷':'▧'}</span><div><b>${item.id} · ${item.name}</b><p>${type==='attendance'?`${item.task} · ${dateVN(item.date)} · ${item.hours} giờ`:`${item.type==='OT'?'Làm thêm giờ':'Nghỉ phép'} · ${dateVN(item.start)}${item.start!==item.end?' – '+dateVN(item.end):''} · ${item.reason}`}</p></div></div><div id="reviewError" class="api-error" style="display:none"></div><div class="modal-footer"><button class="btn btn-quiet" data-review="Rejected">Từ chối</button><button class="btn btn-primary" data-review="Approved">Duyệt yêu cầu</button></div>`;$('#modalBackdrop').classList.add('open');$$('[data-review]').forEach(b=>b.onclick=async()=>{try{if(type==='attendance'){await api(`${apiPaths.attendance}/${encodeURIComponent(item.id)}/${b.dataset.review==='Approved'?'approve':'reject'}`,{method:'PUT',...(b.dataset.review==='Rejected'?{body:JSON.stringify({LydoTuChoi:prompt('Nhập lý do từ chối:')||'Không đáp ứng yêu cầu'})}:{})})}else{let body;if(b.dataset.review==='Rejected'){const reason=prompt('Nhập lý do từ chối:');if(!reason?.trim())return;body=JSON.stringify({LydoTuChoi:reason.trim()})}await api(`${apiPaths.leave}/${encodeURIComponent(item.id)}/${b.dataset.review==='Approved'?'approve':'reject'}`,{method:'PUT',...(body?{body}:{})})}$('#modalBackdrop').classList.remove('open');if(type==='attendance')state.attendanceLoaded=false;else state.leaveLoaded=false;await loadDataFor(currentPage);toast(`${item.id} đã được ${b.dataset.review==='Approved'?'duyệt':'từ chối'}.`)}catch(error){const box=$('#reviewError');box.textContent=error.message;box.style.display='block'}});$$('[data-action="close-modal"]').forEach(b=>b.onclick=()=>$('#modalBackdrop').classList.remove('open'))}
async function completePayroll(){const run=state.payRuns.find(r=>r.status==='Draft');if(!run){toast('Không tìm thấy kỳ lương bản nháp để hoàn tất.');return}try{await api(`${apiPaths.payRuns}/${encodeURIComponent(run.id)}/complete`,{method:'PUT'});state.payRunsLoaded=false;await loadDataFor(currentPage);toast(`Kỳ lương ${run.id} đã hoàn tất.`)}catch(error){toast(error.message)}}
async function exportCurrentPage(){if(currentPage==='leave'){try{const content=await api(`${apiPaths.leave}/export/csv`);const blob=new Blob([content],{type:'text/csv;charset=utf-8'});const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download='bao-cao-nghi-ot.csv';link.click();URL.revokeObjectURL(link.href)}catch(error){toast(error.message)}return}toast('API hiện chưa có endpoint xuất dữ liệu cho màn hình này.')}
function navigate(page){if(!canAccessPage(page)){toast('Tài khoản của bạn không có quyền mở màn hình này.');return}currentPage=page;globalQuery='';render();window.scrollTo(0,0);$('#sidebar').classList.remove('open');loadDataFor(page)}
$$('.nav-item').forEach(n=>n.addEventListener('click',()=>navigate(n.dataset.page)));$('#mobileMenu').onclick=()=>$('#sidebar').classList.toggle('open');$('#signOut').onclick=()=>logout();$('#modalBackdrop').onclick=e=>{if(e.target.id==='modalBackdrop')e.currentTarget.classList.remove('open')};document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#globalSearch').focus()}if(e.key==='Escape')$('#modalBackdrop').classList.remove('open')});render();
